from pathlib import Path
import csv
import re
import sys

CSV_DATEI = Path("reime.csv")
AUSGABE_DATEI = Path("index.html")
VERSION = "2.06"

HTML_VOR_DATEN = '<!DOCTYPE html>\n<html lang="de">\n<head>\n  <meta charset="UTF-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1.0">\n  <title>Deutsches Online-Reimlexikon</title>\n  <style>\n    :root {\n      --bg-color: #0f172a;\n      --card-bg: #1e293b;\n      --border-color: #334155;\n      --primary-color: #38bdf8;\n      --primary-hover: #0284c7;\n      --text-main: #f8fafc;\n      --text-muted: #94a3b8;\n      --accent-gold: #f59e0b;\n    }\n    * { box-sizing: border-box; margin: 0; padding: 0; }\n    body { font-family: \'Segoe UI\', system-ui, sans-serif; background-color: var(--bg-color); color: var(--text-main); line-height: 1.6; padding: 20px 15px; }\n    .container { max-width: 900px; margin: 0 auto; }\n    header { text-align: center; margin-bottom: 30px; padding: 20px 0; border-bottom: 1px solid var(--border-color); }\n    header h1 { font-size: 2.2rem; color: var(--primary-color); margin-bottom: 8px; }\n    header p { color: var(--text-muted); font-size: 1.05rem; }\n    .search-section { background: var(--card-bg); border: 1px solid var(--border-color); border-radius: 12px; padding: 25px; margin-bottom: 30px; }\n    .search-box { display: flex; gap: 12px; flex-wrap: wrap; }\n    .input-wrapper { flex: 1; min-width: 240px; }\n    input[type="text"] { width: 100%; padding: 14px 18px; font-size: 1.1rem; border: 2px solid var(--border-color); border-radius: 8px; background: #0f172a; color: #fff; outline: none; }\n    input[type="text"]:focus { border-color: var(--primary-color); }\n    button.btn-search { padding: 14px 28px; font-size: 1.05rem; font-weight: 600; background: var(--primary-hover); color: white; border: none; border-radius: 8px; cursor: pointer; }\n    button.btn-search:hover { background: var(--primary-color); color: #0f172a; }\n    .filter-options { display: flex; gap: 20px; margin-top: 15px; padding-top: 15px; border-top: 1px solid var(--border-color); font-size: 0.9rem; color: var(--text-muted); }\n    .status-bar { margin-bottom: 20px; font-size: 0.95rem; color: var(--text-muted); display: flex; justify-content: space-between; align-items: center; }\n    .badge { background: #334155; color: var(--primary-color); padding: 4px 10px; border-radius: 20px; font-weight: bold; font-size: 0.85rem; }\n    .results-grid {\n      display: grid;\n      grid-template-columns: repeat(auto-fill, minmax(210px, 1fr));\n      gap: 12px;\n      align-items: stretch;\n    }\n    .word-card {\n      background: var(--card-bg);\n      border: 1px solid var(--border-color);\n      padding: 14px 16px;\n      border-radius: 8px;\n      text-align: center;\n      font-size: 1.05rem;\n      font-weight: 500;\n      min-width: 0;\n      white-space: nowrap;\n      overflow: hidden;\n      text-overflow: clip;\n    }\n    .word-card.search-word { border-color: var(--accent-gold); color: var(--accent-gold); font-weight: 700; box-shadow: 0 0 0 1px rgba(245, 158, 11, 0.25); }\n    footer { margin-top: 34px; padding-top: 18px; border-top: 1px solid var(--border-color); text-align: center; color: var(--text-muted); font-size: 0.85rem; }\n    .empty-state { text-align: center; padding: 40px; background: var(--card-bg); border-radius: 12px; border: 1px dashed var(--border-color); color: var(--text-muted); }\n  \n    .word-card.long-word {\n      font-size: 0.96rem;\n    }\n    .word-card.very-long-word {\n      font-size: 0.88rem;\n      grid-column: span 2;\n    }\n    @media (max-width: 620px) {\n      .results-grid {\n        grid-template-columns: 1fr;\n      }\n      .word-card.very-long-word {\n        grid-column: span 1;\n      }\n    }\n      .case-separator {\n      grid-column: 1 / -1;\n      height: 10px;\n    }\n  \n    .word-card {\n      cursor: pointer;\n      position: relative;\n      transition:\n        background-color 0.15s ease,\n        border-color 0.15s ease,\n        color 0.15s ease,\n        transform 0.08s ease;\n      user-select: none;\n    }\n    .word-card:hover {\n      background: #27364b;\n      border-color: var(--primary-color);\n    }\n    .word-card:active {\n      transform: scale(0.98);\n    }\n    .word-card.copied {\n      background: #14532d;\n      border-color: #4ade80;\n      color: #dcfce7;\n    }\n    .word-card.copied::after {\n      content: "✓";\n      position: absolute;\n      top: 4px;\n      right: 8px;\n      color: #86efac;\n      font-weight: 800;\n      font-size: 1rem;\n    }\n\n    .group-result {\n      margin-bottom: 30px;\n    }\n    .group-result + .group-result {\n      border-top: 1px solid var(--border-color);\n      padding-top: 24px;\n    }\n    .group-heading {\n      margin: 0 0 12px 2px;\n      color: var(--primary-color);\n      font-size: 1.15rem;\n      font-weight: 700;\n    }\n\n  \n    .word-card em {\n      font-style: italic;\n      font-weight: inherit;\n    }\n  </style>\n</head>\n<body>\n  <div class="container">\n    <header>\n<img src="https://imgur.com/oYc2rIO.jpeg" alt="Logo" style="display: block; margin: 0 auto 15px auto; max-width: 90px; height: auto;">\n      <h1>Online-Reimlexikon</h1>\n      <p>Finde reine und unreine Reime für Gedichte & Songtexte</p>\n    </header>\n\n    <div class="search-section">\n      <div class="search-box">\n        <div class="input-wrapper">\n          <input type="text" id="searchInput" placeholder="Reim oder Wort suchen" autocomplete="off" onkeyup="if(event.key===\'Enter\') searchRhymes()">\n        </div>\n        <button class="btn-search" onclick="searchRhymes()">Suchen</button>\n      </div>\n      <div class="filter-options">\n        <label><input type="checkbox" id="sortAlpha" checked onchange="searchRhymes()"> Nach Wortenden sortieren</label>\n        <label><input type="checkbox" id="ignoreCase" checked onchange="searchRhymes()"> Groß-/Kleinschreibung ignorieren</label>\n      </div>\n    </div>\n\n    <div class="status-bar">\n      <span id="statusMessage">Reim oder Wort suchen.</span>\n      <span class="badge" id="wordCountBadge">0 Wörter geladen</span>\n    </div>\n\n    <div id="resultsContainer">\n      <div class="empty-state">Gib oben einen Reim oder ein Wort ein.</div>\n    </div>\n    <footer>Reimlexikon – Version 2.06<br>© Faltsch Wagoni 2026</footer>\n  </div>\n\n  <script>\n    // =========================================================================\n    // DIREKTE REIM-DATENBANK (KEINE EXTERNE CSV MEHR NÖTIG!)\n    // Jede Zeile steht für eine Reim-Gruppe (mit Semikolon getrennt).\n    // =========================================================================\n    const csvData = `'
HTML_NACH_DATEN = '`;\n\n    let rhymeGroups = [];\n    let uniqueWordSet = new Set();\n\n    function normalizeWord(word, ignoreCase) {\n      const cleaned = word.replace(/"/g, \'\').trim();\n      return ignoreCase ? cleaned.toLocaleLowerCase(\'de\') : cleaned;\n    }\n\n    function reverseWord(word) {\n      return Array.from(word).reverse().join(\'\');\n    }\n\n    function compareByEnding(a, b) {\n      const reversedA = reverseWord(a.toLocaleLowerCase(\'de\'));\n      const reversedB = reverseWord(b.toLocaleLowerCase(\'de\'));\n\n      const endingComparison = reversedA.localeCompare(\n        reversedB,\n        \'de\',\n        { sensitivity: \'base\', numeric: true }\n      );\n\n      if (endingComparison !== 0) return endingComparison;\n      if (a.length !== b.length) return a.length - b.length;\n\n      return a.localeCompare(b, \'de\', { sensitivity: \'base\', numeric: true });\n    }\n\n    function initDatabase() {\n      const lines = csvData.trim().split(/\\r?\\n/);\n      uniqueWordSet = new Set();\n\n      rhymeGroups = lines\n        .map(line => {\n          const fields = line.split(\';\')\n            .map(field => field.replace(/"/g, \'\').trim())\n            .filter(field => field.length > 0);\n\n          if (fields.length < 2 || fields[0].toLocaleLowerCase(\'de\') === \'reime\') {\n            return null;\n          }\n\n          const groupName = fields[0];\n          const words = fields.slice(1);\n\n          words.forEach(word => uniqueWordSet.add(word.toLocaleLowerCase(\'de\')));\n          return { name: groupName, words };\n        })\n        .filter(Boolean);\n\n      document.getElementById(\'wordCountBadge\').innerText =\n        `${uniqueWordSet.size.toLocaleString(\'de-DE\')} Wörter geladen`;\n    }\n\n    function wordWithoutNote(word) {\n      return word.replace(/\\s*\\([^)]*\\)\\s*$/u, \'\').trim();\n    }\n\n    function formatWordWithItalicNotes(word) {\n      const safe = escapeHtml(word);\n      return safe.replace(/(\\([^)]*\\))/g, \'<em>$1</em>\');\n    }\n\n    function searchRhymes() {\n      const inputElement = document.getElementById(\'searchInput\');\n      const rawInput = inputElement.value.replace(/"/g, \'\').trim();\n      const ignoreCase = document.getElementById(\'ignoreCase\').checked;\n      const sortByEnding = document.getElementById(\'sortAlpha\').checked;\n      const status = document.getElementById(\'statusMessage\');\n      const container = document.getElementById(\'resultsContainer\');\n\n      if (!rawInput) {\n        status.innerText = \'Reim oder Wort suchen.\';\n        container.innerHTML =\n          \'<div class="empty-state">Gib oben einen Reim oder ein Wort ein.</div>\';\n        return;\n      }\n\n      const normalizedInput = normalizeWord(rawInput, ignoreCase);\n\n      // 1. Exakte Wortsuche:\n      // Ein Wort darf absichtlich in mehreren Reimgruppen vorkommen.\n      let selectedGroups = rhymeGroups.filter(group =>\n        group.words.some(word => normalizeWord(wordWithoutNote(word), ignoreCase) === normalizedInput)\n      );\n\n      // 2. Falls kein Wort gefunden wurde: exakte Reimgruppe suchen.\n      if (selectedGroups.length === 0) {\n        selectedGroups = rhymeGroups.filter(group =>\n          normalizeWord(group.name, ignoreCase) === normalizedInput\n        );\n      }\n\n      if (selectedGroups.length === 0) {\n        status.innerText = `Keine Treffer für „${rawInput}“`;\n        container.innerHTML =\n          `<div class="empty-state">Keine Reimgruppe für <strong>„${escapeHtml(rawInput)}“</strong> gefunden.</div>`;\n        return;\n      }\n\n      container.innerHTML = \'\';\n\n      let totalWords = 0;\n\n      selectedGroups.forEach(group => {\n        // Innerhalb jeder Reimgruppe doppelte Schreibweisen nur einmal anzeigen.\n        const matches = new Map();\n        group.words.forEach(word => {\n          const key = normalizeWord(word, ignoreCase);\n          if (!matches.has(key)) matches.set(key, word);\n        });\n\n        const results = Array.from(matches.values());\n        totalWords += results.length;\n\n        const lowercaseWords = results.filter(word => {\n          const firstLetter = word.match(/[A-Za-zÄÖÜäöüß]/);\n          return !firstLetter || firstLetter[0] === firstLetter[0].toLocaleLowerCase(\'de\');\n        });\n\n        const uppercaseWords = results.filter(word => {\n          const firstLetter = word.match(/[A-Za-zÄÖÜäöüß]/);\n          return firstLetter &&\n            firstLetter[0] === firstLetter[0].toLocaleUpperCase(\'de\') &&\n            firstLetter[0] !== firstLetter[0].toLocaleLowerCase(\'de\');\n        });\n\n        if (sortByEnding) {\n          lowercaseWords.sort(compareByEnding);\n          uppercaseWords.sort(compareByEnding);\n        }\n\n        const section = document.createElement(\'section\');\n        section.className = \'group-result\';\n\n        const heading = document.createElement(\'div\');\n        heading.className = \'group-heading\';\n        heading.innerText =\n          `Reim auf -${group.name.toLocaleLowerCase(\'de\')} · ${results.length.toLocaleString(\'de-DE\')} Reimwörter`;\n        section.appendChild(heading);\n\n        const grid = document.createElement(\'div\');\n        grid.className = \'results-grid\';\n\n        function appendWordCard(word) {\n          const card = document.createElement(\'div\');\n          card.className = \'word-card\';\n\n          if (normalizeWord(wordWithoutNote(word), ignoreCase) === normalizedInput) {\n            card.classList.add(\'search-word\');\n            card.setAttribute(\'aria-label\', `${word}, gesuchtes Wort`);\n          }\n\n          if (word.length >= 24) {\n            card.classList.add(\'very-long-word\');\n          } else if (word.length >= 18) {\n            card.classList.add(\'long-word\');\n          }\n\n          card.innerHTML = formatWordWithItalicNotes(word);\n          card.title = word;\n          grid.appendChild(card);\n        }\n\n        lowercaseWords.forEach(appendWordCard);\n\n        if (lowercaseWords.length > 0 && uppercaseWords.length > 0) {\n          const separator = document.createElement(\'div\');\n          separator.className = \'case-separator\';\n          separator.setAttribute(\'aria-hidden\', \'true\');\n          grid.appendChild(separator);\n        }\n\n        uppercaseWords.forEach(appendWordCard);\n        section.appendChild(grid);\n        container.appendChild(section);\n      });\n\n      if (selectedGroups.length === 1) {\n        status.innerText =\n          `1 Reimgruppe gefunden · ${totalWords.toLocaleString(\'de-DE\')} Reimwörter`;\n      } else {\n        status.innerText =\n          `${selectedGroups.length.toLocaleString(\'de-DE\')} Reimgruppen für „${rawInput}“ gefunden`;\n      }\n    }\n\n    function escapeHtml(text) {\n      return text\n        .replace(/&/g, \'&amp;\')\n        .replace(/</g, \'&lt;\')\n        .replace(/>/g, \'&gt;\')\n        .replace(/"/g, \'&quot;\')\n        .replace(/\'/g, \'&#039;\');\n    }\n\n    initDatabase();\n  \n    async function copyRhymingWord(word, card) {\n      let copied = false;\n\n      try {\n        if (navigator.clipboard && window.isSecureContext) {\n          await navigator.clipboard.writeText(word);\n          copied = true;\n        }\n      } catch (error) {\n        copied = false;\n      }\n\n      if (!copied) {\n        const helper = document.createElement(\'textarea\');\n        helper.value = word;\n        helper.setAttribute(\'readonly\', \'\');\n        helper.style.position = \'fixed\';\n        helper.style.left = \'-9999px\';\n        helper.style.opacity = \'0\';\n        document.body.appendChild(helper);\n        helper.select();\n\n        try {\n          copied = document.execCommand(\'copy\');\n        } catch (error) {\n          copied = false;\n        }\n\n        document.body.removeChild(helper);\n      }\n\n      if (copied) {\n        card.classList.add(\'copied\');\n        window.setTimeout(() => {\n          card.classList.remove(\'copied\');\n        }, 700);\n      }\n    }\n\n    function activateWordCopying() {\n      const results = document.getElementById(\'resultsContainer\');\n      if (!results || results.dataset.copyActive === \'yes\') return;\n\n      results.dataset.copyActive = \'yes\';\n\n      results.addEventListener(\'click\', event => {\n        const card = event.target.closest(\'.word-card\');\n        if (!card || !results.contains(card)) return;\n\n        const word = card.textContent.replace(\'✓\', \'\').trim();\n        if (word) {\n          copyRhymingWord(word, card);\n        }\n      });\n\n      results.addEventListener(\'mouseover\', event => {\n        const card = event.target.closest(\'.word-card\');\n        if (card) {\n          card.title = card.textContent.trim() + \' – zum Kopieren anklicken\';\n        }\n      });\n    }\n\n    activateWordCopying();\n\n  </script>\n</body>\n</html>\n'


def lese_reime(csv_datei):
    gruppen = []

    with csv_datei.open("r", encoding="utf-8-sig", newline="") as f:
        reader = csv.reader(f, delimiter=";")

        for zeilennummer, zeile in enumerate(reader, start=1):
            felder = [feld.strip() for feld in zeile if feld.strip()]

            if not felder:
                continue

            if len(felder) < 2:
                print(
                    f"Warnung: Zeile {zeilennummer} enthält keine Reimwörter "
                    f"und wird ausgelassen: {felder[0]}"
                )
                continue

            gruppen.append(felder)

    return gruppen


def sichere_javascript_daten(text):
    return (
        text.replace("\\", "\\\\")
            .replace("`", "\\`")
            .replace("${", "\\${")
    )


def baue_html(gruppen):
    daten_zeilen = [";".join(gruppe) for gruppe in gruppen]
    daten = sichere_javascript_daten("\n".join(daten_zeilen))

    html = HTML_VOR_DATEN + daten + HTML_NACH_DATEN

    html = re.sub(
        r"Reimlexikon\s*[–-]\s*Version\s+\d+\.\d+",
        f"Reimlexikon – Version {VERSION}",
        html,
        count=1,
    )
    return html


def main():
    if not CSV_DATEI.exists():
        print("Fehler: reime.csv wurde nicht gefunden.")
        print("Lege reime.csv und reimlexikon_builder_2_06.py in denselben Ordner.")
        sys.exit(1)

    gruppen = lese_reime(CSV_DATEI)

    if not gruppen:
        print("Fehler: In reime.csv wurden keine gültigen Reimgruppen gefunden.")
        sys.exit(1)

    html = baue_html(gruppen)
    AUSGABE_DATEI.write_text(html, encoding="utf-8")

    anzahl_woerter = sum(len(gruppe) - 1 for gruppe in gruppen)

    print("Fertig!")
    print("Erstellt:", AUSGABE_DATEI.name)
    print("Version:", VERSION)
    print("Reimgruppen:", len(gruppen))
    print("Reimwörter:", anzahl_woerter)


if __name__ == "__main__":
    main()
